cli.mjs.text:
#!/usr/bin/env node
// Zero-dependency CLI: checks that every literal file target named in a
// package.json "exports" map actually exists on disk, relative to the
// package.json's own directory. No network call, ever -- reads only the
// package.json file named on the command line.
//
//   node cli.mjs check                          # ./package.json
//   node cli.mjs check path/to/package.json
//   node cli.mjs check --json
//
// Run this AFTER your build step and BEFORE `npm publish` -- it checks what
// is on disk right now, so run it before the build has produced anything and
// every export will read as missing.

import fs from "node:fs/promises";
import path from "node:path";
import {
  parsePackageJson,
  extractExportEntries,
  classifyExportEntries,
  diffExports,
  summarize,
} from "./engine.mjs";

function parseArgs(argv) {
  const args = { json: false, positional: [] };
  for (const a of argv) {
    if (a === "--json") args.json = true;
    else if (a === "--help" || a === "-h") args.help = true;
    else if (!args.sub && !a.startsWith("-")) args.sub = a;
    else if (a.startsWith("-")) args.unknown = a;
    else args.positional.push(a);
  }
  return args;
}

function renderReport(report, { wildcard, external }) {
  const { status, text } = summarize(report, { wildcardCount: wildcard.length, externalCount: external.length });
  const lines = [text];
  for (const m of report.missing) {
    const cond = m.condition ? ` [${m.condition}]` : "";
    lines.push(`  MISSING  ${m.subpath}${cond}  ->  ${m.target}`);
  }
  return { status, lines };
}

export async function run(
  argv,
  {
    readFile = (p) => fs.readFile(p, "utf8"),
    stat = (p) => fs.stat(p),
  } = {},
) {
  const args = parseArgs(argv);

  if (args.help || !args.sub) {
    return {
      exitCode: args.help ? 0 : 1,
      output: [
        "Usage:",
        "  node cli.mjs check [path/to/package.json] [--json]",
        "",
        "Flattens the package.json \"exports\" map (subpaths, nested conditions,",
        "and fallback arrays) and checks that every literal file target actually",
        "exists on disk, relative to the package.json's own directory. Wildcard",
        "targets (\"./features/*\") and bare-specifier re-exports of another",
        "package are listed as not checked, not as missing. No network call --",
        "reads only the named file. Run this after your build step and before",
        "`npm publish`. Exit 1 if any literal target is missing.",
      ].join("\n"),
    };
  }

  if (args.sub !== "check") {
    return { exitCode: 2, output: `Unknown subcommand "${args.sub}". Try --help.` };
  }

  const pkgPath = args.positional[0] || "package.json";
  let pkgText;
  try {
    pkgText = await readFile(pkgPath);
  } catch (err) {
    return { exitCode: 2, output: `Cannot read ${pkgPath}: ${err.message}` };
  }

  let pkg;
  try {
    pkg = parsePackageJson(pkgText);
  } catch (err) {
    return { exitCode: 2, output: `${pkgPath}: ${err.message}` };
  }

  const entries = extractExportEntries(pkg.exports);
  if (entries.length === 0) {
    return { exitCode: 0, output: `${pkgPath}: no "exports" field (or it is empty) -- nothing to check.` };
  }

  const { literal, wildcard, external } = classifyExportEntries(entries);
  const baseDir = path.dirname(pkgPath);

  const targetExists = new Map();
  for (const entry of literal) {
    if (targetExists.has(entry.target)) continue;
    try {
      await stat(path.join(baseDir, entry.target));
      targetExists.set(entry.target, true);
    } catch {
      targetExists.set(entry.target, false);
    }
  }
  const existsFn = (target) => targetExists.get(target) === true;

  const report = diffExports({ literal, fileExists: existsFn });
  const exitCode = report.missing.length > 0 ? 1 : 0;

  if (args.json) {
    return {
      exitCode,
      output: JSON.stringify(
        {
          packageJson: pkgPath,
          missing: report.missing,
          matched: report.matched,
          wildcardSkipped: wildcard,
          externalSkipped: external,
        },
        null,
        2,
      ),
    };
  }

  const { lines } = renderReport(report, { wildcard, external });
  lines.unshift(`${pkgPath}: checked ${literal.length} export target(s)`);
  return { exitCode, output: lines.join("\n") };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { exitCode, output } = await run(process.argv.slice(2));
  console.log(output);
  process.exitCode = exitCode;
}

engine.mjs.text:
// Zero-dependency, deterministic diff between a package.json "exports" map's
// literal file targets and the files that actually exist on disk (CLI) or
// were pasted as a file listing (browser page). No network access here --
// callers (cli.mjs, index.html) supply the package.json text and the file
// list; this module only parses and compares.
//
// This is a publish-safety check, not a bundler: it never runs the package,
// never resolves imports, and never reads a file's contents -- only whether
// each literal path the "exports" map names actually exists.

/**
 * Parses package.json text. Throws a short, human-readable Error on invalid
 * JSON rather than letting JSON.parse's cryptic message through.
 */
export function parsePackageJson(text) {
  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error(`not valid JSON: ${err.message}`);
  }
}

// Recursively walks a node of the "exports" value, appending one entry per
// leaf string target it finds. `condPath` accumulates the chain of condition
// keys (e.g. ["import", "types"]) purely for reporting -- it plays no part
// in which paths get checked, because a customer's runtime picks exactly one
// branch and a maintainer cannot know in advance which one, so every branch
// that names a file is checked.
function walkExportsValue(value, subpath, condPath, out) {
  if (value === null || value === undefined) return; // explicit "not exported" -- not a file target
  if (typeof value === "string") {
    out.push({ subpath, condition: condPath.join(" > ") || null, target: value });
    return;
  }
  if (Array.isArray(value)) {
    for (const v of value) walkExportsValue(v, subpath, condPath, out);
    return;
  }
  if (typeof value === "object") {
    for (const [key, v] of Object.entries(value)) walkExportsValue(v, subpath, [...condPath, key], out);
  }
}

/**
 * Flattens a package.json "exports" field (any of its shapes: a bare
 * string, a subpath map, a nested condition map, or fallback arrays at any
 * level) into a flat list of { subpath, condition, target } entries, one per
 * leaf string. Returns [] for a missing/null exports field.
 */
export function extractExportEntries(exportsField) {
  const entries = [];
  if (exportsField == null) return entries;
  if (typeof exportsField === "string" || Array.isArray(exportsField)) {
    walkExportsValue(exportsField, ".", [], entries);
    return entries;
  }
  if (typeof exportsField === "object") {
    const keys = Object.keys(exportsField);
    const isSubpathMap = keys.length > 0 && keys.every((k) => k.startsWith("."));
    if (isSubpathMap) {
      for (const [subpath, v] of Object.entries(exportsField)) walkExportsValue(v, subpath, [], entries);
    } else {
      // A bare condition map (import/require/types/...) for the root ".".
      walkExportsValue(exportsField, ".", [], entries);
    }
  }
  return entries;
}

/**
 * Splits flattened entries into three groups:
 *   literal  -- a relative file path ("./..." or "../...") with no glob --
 *               the only group whose existence this tool can check.
 *   wildcard -- contains "*" (e.g. "./features/*"); resolving one requires
 *               matching real files against a pattern, out of scope for v0.
 *   external -- does not start with "." at all (a bare specifier re-exporting
 *               another package's subpath) -- nothing on disk to check.
 */
export function classifyExportEntries(entries) {
  const literal = [];
  const wildcard = [];
  const external = [];
  for (const entry of entries) {
    if (entry.target.includes("*")) wildcard.push(entry);
    else if (entry.target.startsWith(".")) literal.push(entry);
    else external.push(entry);
  }
  return { literal, wildcard, external };
}

/** Strips one leading "./" so a target and a listed file compare equal regardless of which form either was written in. */
export function normalizePath(p) {
  return String(p ?? "").trim().replace(/\\/g, "/").replace(/^\.\//, "");
}

/**
 * Parses a newline-separated file listing (e.g. `git ls-files`, `find . -type f`)
 * into a Set of normalized relative paths.
 */
export function parseFileList(text) {
  const files = new Set();
  for (const raw of String(text ?? "").split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    files.add(normalizePath(line));
  }
  return files;
}

/**
 * Compares literal export entries against a set of files known to exist.
 * `fileExists(target)` receives the *original* (unnormalized) target string
 * so a filesystem-backed caller (cli.mjs) can resolve it relative to the
 * package.json's own directory; a text-listing caller (index.html) can pass
 * `(t) => fileSet.has(normalizePath(t))` instead.
 */
export function diffExports({ literal, fileExists }) {
  const missing = [];
  const matched = [];
  for (const entry of literal) {
    if (fileExists(entry.target)) matched.push(entry);
    else missing.push(entry);
  }
  missing.sort((a, b) => a.target.localeCompare(b.target) || a.subpath.localeCompare(b.subpath));
  return { missing, matched };
}

export function summarize(report, { wildcardCount = 0, externalCount = 0 } = {}) {
  const skippedNote = wildcardCount > 0 || externalCount > 0
    ? ` (${wildcardCount ? `${wildcardCount} wildcard` : ""}${wildcardCount && externalCount ? ", " : ""}${externalCount ? `${externalCount} external` : ""} entr${wildcardCount + externalCount === 1 ? "y" : "ies"} not checked)`
    : "";
  if (report.missing.length === 0) {
    return {
      status: "ok",
      text: report.matched.length > 0
        ? `${report.matched.length} export target(s) exist -- nothing missing.${skippedNote}`
        : `No checkable literal export targets found.${skippedNote}`,
    };
  }
  return {
    status: "missing",
    text: `${report.missing.length} export target(s) named in package.json do not exist.${skippedNote}`,
  };
}

usage.mjs.text:
const KEY = "package-exports-drift-check-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "package-exports-drift-check-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
    try { localStorage.setItem(OPT_OUT, "1"); } catch { /* storage is optional */ }
  } else {
    try { localStorage.removeItem(OPT_OUT); } catch { /* storage is optional */ }
  }
}

export { usageOptedOut };
